import{demoCreators}from './data.js';const c=demoCreators.find(c=>c.id===new URLSearchParams(location.search).get('creator'));const el=document.querySelector('#sample');if(c){el.innerHTML='<span class="pill lime">FICTIONAL CONTENT EXAMPLE</span><h1></h1><h2></h2><p>This is a local sample brief, not a published video or evidence of a real creator. It illustrates the kind of content the team could evaluate after importing verified creator records.</p><section class="panel"><h3>Example editorial outline</h3><p>Introduce the gaming setup and its intended user. Explain component choices and the testing method. Show the strengths, limitations and open questions. Distinguish measurements from personal impressions.</p><h3>What to verify before outreach</h3><p>Replace this brief with a real channel and video URL, publication date, observed performance, sponsorship disclosures and a source for any audience claims.</p></section>';el.querySelector('h1').textContent=c.contentTitle;el.querySelector('h2').textContent=c.name+' · '+c.platform;}else el.textContent='Sample not found.';